// RestoreGraphFrozenGraph eagerly materializes a buffer into a fresh Arena (shared and cyclic
// nodes materialize once).
func RestoreGraphFrozenGraph(buf []byte) (*Arena, error) {
	acc, err := OpenGraphFrozenGraph(buf)
	if err != nil {
		return nil, err
	}
	a := NewArena()
	a.SetRoot(restoreBook(acc, a, map[dagr.SeenKey]uint64{}))
	return a, nil
}
